<script setup>
import {ref,watch,onMounted,onUnmounted} from 'vue'
import {buildWorld,drawTile,drawPerson,palettes,targets,exit,spawn} from '../../lib/dungeonWorld'
const props=defineProps({level:{type:Number,default:1},hero:{type:String,default:'ranger'},solved:{type:Number,default:0},active:Boolean}),emit=defineEmits(['interact','collect','position']),canvas=ref(null),host=ref(null),position=ref({x:4,y:22});let world=buildWorld(props.level),player={x:4,y:22},keys=new Set(),frame,last=0,moving=false,direction='down',observer,ctx,w=300,h=180,steps=0,collected=new Set(),alive=true
const items=[[6,22],[15,16],[29,16]]
function resize(){if(!host.value)return;w=Math.max(160,Math.floor(host.value.clientWidth/3));h=Math.max(100,Math.floor(host.value.clientHeight/3));canvas.value.width=w;canvas.value.height=h;ctx=canvas.value.getContext('2d');ctx.imageSmoothingEnabled=false}
function reset(){world=buildWorld(props.level);player={x:spawn[0],y:spawn[1]};position.value={...player};collected=new Set();keys.clear();last=0;canvas.value?.focus({preventScroll:true})}
watch(()=>props.level,reset);watch(()=>props.active,value=>{keys.clear();if(value)canvas.value?.focus({preventScroll:true})})
function walkable(x,y){const ix=Math.round(x),iy=Math.round(y),tile=world.tiles[iy]?.[ix];if(tile==null||tile===2||tile===3)return false;if(ix===exit[0]&&iy===exit[1]&&props.solved<4)return false;if(props.level===2&&iy===16&&ix>=14&&ix<=16&&props.solved<1)return false;if(props.level===3&&ix===19&&iy>=11&&iy<=13&&props.solved<2)return false;if(props.level===3&&ix===12&&iy===18&&props.solved<1)return false;return true}
function interact(){if(!props.active)return;const target=props.level===5?[24,12]:targets[Math.min(props.solved,3)],distance=Math.hypot(player.x-target[0],player.y-target[1]);if(distance<2.2)emit('interact',{kind:'npc',index:Math.min(props.solved,3)});else if(Math.hypot(player.x-exit[0],player.y-exit[1])<2.2)emit('interact',{kind:'exit'});else{const nearby=targets.findIndex(t=>Math.hypot(player.x-t[0],player.y-t[1])<2.2);emit('interact',nearby>=0?{kind:'npc',index:nearby}:{kind:'empty'})}}
function keydown(e){if(!props.active||document.hidden||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d','e',' '].includes(key)){e.preventDefault();if(key==='e'||key===' '){if(!e.repeat)interact()}else keys.add(key)}}
function keyup(e){keys.delete(e.key.toLowerCase())}function blur(){keys.clear()}
function touch(key,down){if(down){keys.clear();keys.add(key)}else keys.delete(key)}
function tick(now){if(!alive)return;const dt=last?Math.min((now-last)/1000,.04):0;last=now;moving=false;if(!props.active||document.hidden||document.querySelector('dialog[open]'))keys.clear();if(props.active&&!document.hidden&&!document.querySelector('dialog[open]')){let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(dx||dy){direction=Math.abs(dx)>=Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up';const length=Math.hypot(dx,dy),speed=4*dt;dx=dx/length*speed;dy=dy/length*speed;if(walkable(player.x+dx,player.y))player.x+=dx;if(walkable(player.x,player.y+dy))player.y+=dy;moving=true;steps+=dt;position.value={...player};emit('position',{x:Math.round(player.x),y:Math.round(player.y)});for(let i=0;i<items.length;i++)if(!collected.has(i)&&Math.hypot(player.x-items[i][0],player.y-items[i][1])<.65){collected.add(i);emit('collect','별 조각 '+(i+1))}}}draw(now);frame=requestAnimationFrame(tick)}
function draw(now){if(!ctx)return;const p=palettes[props.level],cx=Math.max(0,Math.min(world.w*16-w,player.x*16-w/2)),cy=Math.max(0,Math.min(world.h*16-h,player.y*16-h/2));ctx.fillStyle=p.dark;ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(-Math.round(cx),-Math.round(cy));for(let y=Math.max(0,Math.floor(cy/16));y<Math.min(world.h,Math.ceil((cy+h)/16));y++)for(let x=Math.max(0,Math.floor(cx/16));x<Math.min(world.w,Math.ceil((cx+w)/16));x++)drawTile(ctx,world.tiles[y][x],x*16,y*16,p,props.level);
 for(let i=0;i<items.length;i++)if(!collected.has(i)){const [x,y]=items[i];ctx.fillStyle='#f4d379';ctx.fillRect(x*16-2,y*16-4,5,8);ctx.fillRect(x*16-4,y*16-1,9,3)}
 if(props.level===1){for(const [hx,hy]of [[4,14],[12,21],[23,20],[31,10]]){const x=hx*16,y=hy*16;ctx.fillStyle='#243c3b';ctx.fillRect(x-2,y-3,44,34);ctx.fillStyle='#c7bb91';ctx.fillRect(x,y,40,28);ctx.fillStyle='#714a3d';ctx.fillRect(x-3,y-10,46,10);ctx.fillStyle='#a27352';ctx.fillRect(x+2,y-15,36,6);ctx.fillStyle='#243746';ctx.fillRect(x+15,y+10,10,18);ctx.fillStyle='#cfd5a7';ctx.fillRect(x+5,y+6,7,7);ctx.fillRect(x+28,y+6,7,7)}}
 if(props.level>=4){const x=34*16,y=1*16;ctx.fillStyle='#273d49';ctx.fillRect(x,y,8*16,3*16);ctx.fillStyle='#8a9b98';ctx.fillRect(x+4,y+8,8*16-8,3*16-8);for(let i=0;i<8;i++){ctx.fillStyle='#b5bda5';ctx.fillRect(x+i*16,y,10,13)}ctx.fillStyle='#233e47';ctx.fillRect(38*16-12,4*16-22,24,28)}
 if(props.level===2){const x=15*16,y=16*16;ctx.fillStyle='#304a3d';ctx.fillRect(x-24,y-12,5,25);ctx.fillRect(x+19,y-12,5,25);ctx.fillStyle=props.solved>=1?'#8eb77c':'#bdab72';if(props.solved<1)ctx.fillRect(x-19,y-5,38,10);else{ctx.fillRect(x-21,y-5,7,10);ctx.fillRect(x+14,y-5,7,10)}}
 if(props.level===3){ctx.fillStyle=props.solved>=1?'#82917b':Math.floor(now/600)%2?'#cb8865':'#a65c4e';ctx.fillRect(12*16-6,18*16-6,12,12);ctx.fillStyle='#263c45';ctx.fillRect(12*16-3,18*16-3,6,6);const x=19*16,y=12*16;ctx.fillStyle=props.solved>=2?'#b6a06c':'#315d71';ctx.fillRect(x-10,y-17,22,38);if(props.solved>=2){ctx.fillStyle='#715e46';for(let i=0;i<5;i++)ctx.fillRect(x-10,y-17+i*8,22,2)}ctx.fillStyle='#efc776';for(const [tx,ty]of [[14,12],[25,16]]){ctx.fillRect(tx*16-2,ty*16-11,4,7);ctx.fillStyle='#8f6847';ctx.fillRect(tx*16-1,ty*16-4,2,11);ctx.fillStyle='#efc776'}}
 if(props.level===5){ctx.fillStyle='#152731';ctx.fillRect(24*16-16,12*16-28,32,36);ctx.fillStyle='#7b9197';ctx.fillRect(24*16-14,12*16-26,28,26);ctx.fillStyle='#c3b56f';ctx.fillRect(24*16-10,12*16-18,6,5);ctx.fillRect(24*16+4,12*16-18,6,5);ctx.fillStyle='#344d59';ctx.fillRect(24*16-7,12*16-6,14,6);ctx.fillStyle='#e3cc70';ctx.font='8px monospace';ctx.fillText('BOSS',24*16-11,12*16-33)}else targets.forEach(([x,y],i)=>{drawPerson(ctx,x*16,y*16,'scholar',0,'down',true);ctx.fillStyle=i<props.solved?'#9fdb8e':'#ffe28a';ctx.font='bold 10px monospace';ctx.fillText(i<props.solved?'✓':String(i+1),x*16-3,y*16-18);if(i===props.solved){ctx.strokeStyle='#f5d774';ctx.strokeRect(x*16-9,y*16-16,18,29)}})
 const [ex,ey]=exit;ctx.fillStyle='#243746';ctx.fillRect(ex*16-10,ey*16-23,20,33);ctx.fillStyle=props.solved>=4?'#8ad6a1':'#bfa66b';ctx.fillRect(ex*16-7,ey*16-20,14,27);ctx.fillStyle='#172a38';ctx.fillRect(ex*16-2,ey*16-12,4,7);drawPerson(ctx,Math.round(player.x*16),Math.round(player.y*16),props.hero,moving?Math.floor(steps*7)%2:0,direction);ctx.restore();ctx.fillStyle='#172a38dd';ctx.fillRect(4,4,94,14);ctx.fillStyle='#f4dd99';ctx.font='8px monospace';ctx.fillText('L'+props.level+'  '+Math.round(player.x)+','+Math.round(player.y),8,14)}
onMounted(()=>{observer=new ResizeObserver(resize);observer.observe(host.value);resize();reset();window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);window.addEventListener('blur',blur);document.addEventListener('visibilitychange',blur);frame=requestAnimationFrame(tick)});onUnmounted(()=>{alive=false;cancelAnimationFrame(frame);observer?.disconnect();keys.clear();window.removeEventListener('keydown',keydown);window.removeEventListener('keyup',keyup);window.removeEventListener('blur',blur);document.removeEventListener('visibilitychange',blur)})
</script>
<template><div class="dungeon-world" ref="host"><canvas ref="canvas" tabindex="0" aria-label="코딩 던전 맵. 방향키 또는 WASD로 이동하고 E로 상호작용하세요."/><span class="world-location">위치 {{Math.round(position.x)}}, {{Math.round(position.y)}}</span><div class="touch-controls"><div class="d-pad"><button aria-label="위로 이동" @pointerdown.prevent="touch('w',true)" @pointerup="touch('w',false)" @pointerleave="touch('w',false)" @pointercancel="blur">▲</button><button aria-label="왼쪽으로 이동" @pointerdown.prevent="touch('a',true)" @pointerup="touch('a',false)" @pointerleave="touch('a',false)" @pointercancel="blur">◀</button><button aria-label="아래로 이동" @pointerdown.prevent="touch('s',true)" @pointerup="touch('s',false)" @pointerleave="touch('s',false)" @pointercancel="blur">▼</button><button aria-label="오른쪽으로 이동" @pointerdown.prevent="touch('d',true)" @pointerup="touch('d',false)" @pointerleave="touch('d',false)" @pointercancel="blur">▶</button></div><button class="interact-touch" @click="interact">E 대화</button></div></div></template>
<style scoped>
.dungeon-world{position:relative;width:100%;height:100%;min-width:0;min-height:280px;overflow:hidden;background:#18312f;isolation:isolate}.dungeon-world canvas{display:block;width:100%;height:100%;image-rendering:pixelated;outline:none;touch-action:none}.world-location{position:absolute;top:8px;right:8px;padding:4px 6px;background:#172a38dd;color:#f4dd99;font:9px monospace;pointer-events:none}.touch-controls{position:absolute;bottom:12px;left:12px;right:12px;display:flex;justify-content:space-between;align-items:end;pointer-events:none}.touch-controls button{pointer-events:auto;touch-action:none;user-select:none}.d-pad{display:grid;grid-template-columns:repeat(3,36px);grid-template-rows:repeat(2,32px);gap:3px;opacity:.85}.d-pad button{padding:0;margin:0;font-size:14px}.d-pad button:first-child{grid-column:2}.d-pad button:nth-child(2){grid-row:2;grid-column:1}.d-pad button:nth-child(3){grid-row:2;grid-column:2}.d-pad button:nth-child(4){grid-row:2;grid-column:3}.interact-touch{padding:9px;font-size:11px;opacity:.9}@media(hover:hover) and (min-width:1000px){.touch-controls{opacity:.6}.touch-controls:hover{opacity:1}}
</style>
